def prd_task_lines(prd_text: str) -> int:
    """Count the PRD's top-level `- [ ]` / `- [x]` checkbox lines."""
    return len(_TASK_LINE.findall(prd_text))


def _tree_block(prd_text: str) -> list[str] | None:
    """Lines inside the fence under `### Repository Structure`, or None
    when the heading is missing or no fence opens before the next heading."""
    lines = prd_text.splitlines()
    start = next(
        (i for i, line in enumerate(lines) if line.startswith(_TREE_HEADING)), None
    )
    if start is None:
        return None
    for i in range(start + 1, len(lines)):
        if lines[i].startswith("#"):
            return None
        if lines[i].startswith("```"):
            body = lines[i + 1 :]
            end = next(
                (j for j, line in enumerate(body) if line.startswith("```")), len(body)
            )
            return body[:end]
    return None


def _ancestors(path: str) -> list[str]:
    """`path` and every directory above it, stopping before "", "." and "/"."""
    out: list[str] = []
    while path and path not in (".", "/"):
        out.append(path)
        path = posixpath.dirname(path)
    return out


def _tree_entries(block: list[str]) -> tuple[set[str], set[str], set[str]]:
    """(explicit dirs, implicit file ancestors, listed files) from the ASCII
    tree, one entry per line, each path normalized before it is recorded."""
    dirs: set[str] = set()
    implicit: set[str] = set()
    files: set[str] = set()
    stack: list[tuple[int, str]] = []
    for raw in block:
        name = raw.split(" #", 1)[0].rstrip()
        depth = 0
        while name[:4] in _TREE_COLUMNS:
            depth += 1
            name = name[4:]
        if not name:
            continue
        while stack and stack[-1][0] >= depth:
            stack.pop()
        path = posixpath.join(stack[-1][1], name) if stack else name
        if not path.endswith("/"):
            path = posixpath.normpath(path)
            files.add(path)
            implicit.update(_ancestors(posixpath.dirname(path)))
            continue
        path = posixpath.normpath(path.rstrip("/"))
        stack.append((depth, path))
        dirs.update(_ancestors(path))
    return dirs, implicit, files


def prd_modules(prd_text: str) -> Modules | None:
    """(sorted leaf dirs, sorted listed files) from the PRD's Repository
    Structure tree, or None when the PRD carries no such fenced tree. A leaf
    is an explicit directory with no recorded descendant; a file entry's
    implicit ancestors are grouping-only, so they demote but never grant."""
    block = _tree_block(prd_text)
    if block is None:
        return None
    dirs, implicit, files = _tree_entries(block)
    known = dirs | implicit
    leaves = [d for d in dirs if not any(o.startswith(d + "/") for o in known)]
    return tuple(sorted(leaves)), tuple(sorted(files))


def _file_module(path: str, modules: Modules) -> tuple[str, bool]:
    """(module, covered) for one task file against the PRD tree."""
    leaf_dirs, listed = modules
    for leaf in leaf_dirs:
        if path.startswith(leaf + "/"):
            return leaf, True
    return posixpath.dirname(path) or ".", path in listed


